fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2 - 60);
        host::display::state_set(2, 120);
        host::display::state_set(3, 1);
        host::display::state_set(4, 0);
        host::display::state_set(20, w / 2 - 60);
        host::display::state_set(21, 120);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(5) == 0;
    host::display::state_set(5, down);
    let height: i32 = host::display::state_get(3);
    if host::display::state_get(4) == 1 {
        host::display::clear(0x101018);
        host::display::draw_string(140, 170, "IT TOPPLED", 0xff4040, 4);
        host::display::draw_string(120, 240, "TOWER HEIGHT", 0x808080, 2);
        host::display::draw_number(360, 234, height, 0xffffff, 3);
        host::display::draw_string(130, 320, "TAP TO STACK AGAIN", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let bx: i32 = host::display::state_get(1);
        let bw: i32 = host::display::state_get(2);
        let span: i32 = w - bw;
        let spd: i32 = 4 + height / 3;
        let mut m: i32 = (t * spd) % (2 * span);
        if m > span { m = 2 * span - m; }
        if tap {
            let mut off: i32 = m - bx;
            if off < 0 { off = -off; }
            if off <= 2 { off = 0; }
            let nw: i32 = bw - off;
            if nw <= 0 {
                host::display::state_set(4, 1);
            } else {
                let mut nx: i32 = bx;
                if m > bx { nx = m; }
                host::display::state_set(1, nx);
                host::display::state_set(2, nw);
                host::display::state_set(3, height + 1);
                host::display::state_set(20 + (height % 12) * 2, nx);
                host::display::state_set(21 + (height % 12) * 2, nw);
            }
        }
        host::display::clear(0x0e1218);
        let mut shown: i32 = height;
        if shown > 12 { shown = 12; }
        let mut k: i32 = 0;
        while k < shown {
            let lvl: i32 = height - shown + k;
            let lx: i32 = host::display::state_get(20 + (lvl % 12) * 2);
            let lw: i32 = host::display::state_get(21 + (lvl % 12) * 2);
            let mut col: i32 = 0x3a6ea5;
            if lvl % 2 == 1 { col = 0x4a86c5; }
            host::display::fill_rect(lx, h - 60 - k * 22, lw, 20, col);
            k = k + 1;
        }
        host::display::fill_rect(m, h - 60 - shown * 22, bw, 20, 0xffcc44);
        host::display::draw_string(8, 8, "HEIGHT", 0x808080, 2);
        host::display::draw_number(130, 8, height, 0xffffff, 2);
        host::display::draw_string(8, 40, "TAP TO DROP THE BLOCK", 0x506070, 1);
    }
    host::display::present();
}
